/**
 * Generated by `createservice subscription.RegisterSubscriptionContextsService --type mutations`
 */

const { faker } = require('@faker-js/faker')
const dayjs = require('dayjs')

const { makeLoggedInAdminClient, makeClient, expectToThrowGQLError, setFeatureFlag } = require('@open-condo/keystone/test.utils')
const { expectToThrowAccessDeniedErrorToResult, expectToThrowAuthenticationErrorToResult } = require('@open-condo/keystone/test.utils')

const { SUBSCRIPTIONS } = require('@condo/domains/common/constants/featureflags')
const { MANAGING_COMPANY_TYPE } = require('@condo/domains/organization/constants/common')
const { registerNewOrganization } = require('@condo/domains/organization/utils/testSchema')
const { SUBSCRIPTION_PERIOD, SUBSCRIPTION_CONTEXT_STATUS, SUBSCRIPTION_PLAN_TYPE_FEATURE, SUBSCRIPTION_PLAN_TYPE_SERVICE } = require('@condo/domains/subscription/constants')
const {
    registerSubscriptionContextsByTestClient,
    createTestSubscriptionPlan,
    createTestSubscriptionPlanPricingRule,
    createTestSubscriptionContext,
    updateTestSubscriptionContext,
    SubscriptionContext,
} = require('@condo/domains/subscription/utils/testSchema')
const { makeClientWithNewRegisteredAndLoggedInUser, makeClientWithSupportUser } = require('@condo/domains/user/utils/testSchema')

const { ERRORS } = require('./RegisterSubscriptionContextsService')

describe('RegisterSubscriptionContextsService', () => {
    let admin, support, user, anonymous
    let organization, subscriptionPlan, pricingRule

    beforeAll(async () => {
        admin = await makeLoggedInAdminClient()
        support = await makeClientWithSupportUser()
        anonymous = await makeClient()

        const [plan] = await createTestSubscriptionPlan(admin, {
            name: faker.commerce.productName(),
            organizationType: MANAGING_COMPANY_TYPE,
            isHidden: false,
            trialDays: 14,
        })
        subscriptionPlan = plan

        const [rule] = await createTestSubscriptionPlanPricingRule(admin, subscriptionPlan, {
            period: SUBSCRIPTION_PERIOD.MONTH,
            price: '1000.00',
            currencyCode: 'RUB',
        })
        pricingRule = rule
    })

    beforeEach(async () => {
        user = await makeClientWithNewRegisteredAndLoggedInUser()
        const [org] = await registerNewOrganization(user, { type: MANAGING_COMPANY_TYPE })
        organization = org
    })

    describe('Access', () => {
        test('admin can register trial subscription', async () => {
            const [result] = await registerSubscriptionContextsByTestClient(admin, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                isTrial: true,
            })

            expect(result.subscriptionContexts[0]).toBeDefined()
            expect(result.subscriptionContexts[0].isTrial).toBe(true)
        })

        test('support can register trial subscription', async () => {
            const [result] = await registerSubscriptionContextsByTestClient(support, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                isTrial: true,
            })

            expect(result.subscriptionContexts[0]).toBeDefined()
            expect(result.subscriptionContexts[0].isTrial).toBe(true)
        })

        test('organization admin can register trial for own organization', async () => {
            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                isTrial: true,
            })

            expect(result.subscriptionContexts[0]).toBeDefined()
            expect(result.subscriptionContexts[0].isTrial).toBe(true)
        })

        test('user cannot register for other organization', async () => {
            const otherUser = await makeClientWithNewRegisteredAndLoggedInUser()
            const [otherOrg] = await registerNewOrganization(otherUser, { type: MANAGING_COMPANY_TYPE })

            await expectToThrowAccessDeniedErrorToResult(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: { id: otherOrg.id },
                    subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                    isTrial: true,
                })
            })
        })

        test('anonymous cannot register', async () => {
            await expectToThrowAuthenticationErrorToResult(async () => {
                await registerSubscriptionContextsByTestClient(anonymous, {
                    organization: { id: organization.id },
                    subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                    isTrial: true,
                })
            })
        })
    })

    describe('Trial Logic', () => {
        test('creates trial subscription context with status DONE and correct dates', async () => {
            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                isTrial: true,
            })

            const context = result.subscriptionContexts[0]
            expect(context.isTrial).toBe(true)
            expect(context.status).toBe(SUBSCRIPTION_CONTEXT_STATUS.DONE)
            expect(context.organization.id).toBe(organization.id)
            expect(context.subscriptionPlan.id).toBe(subscriptionPlan.id)

            const startAt = dayjs(context.startAt)
            const endAt = dayjs(context.endAt)
            expect(endAt.diff(startAt, 'day')).toBe(subscriptionPlan.trialDays)

            expect(result.directPaymentUrl).toBeNull()
            expect(result.multiPayment).toBeNull()
        })

        test('throws error if trial is not available (trialDays = 0)', async () => {
            const [noTrialPlan] = await createTestSubscriptionPlan(admin, {
                name: faker.commerce.productName(),
                organizationType: MANAGING_COMPANY_TYPE,
                isHidden: false,
                trialDays: 0,
            })
            const [noTrialRule] = await createTestSubscriptionPlanPricingRule(admin, noTrialPlan, {
                period: SUBSCRIPTION_PERIOD.MONTH,
                price: '1000.00',
                currencyCode: 'RUB',
            })

            await expectToThrowGQLError(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: { id: organization.id },
                    subscriptionPlanPricingRules: [{ id: noTrialRule.id }],
                    isTrial: true,
                })
            }, ERRORS.TRIAL_NOT_AVAILABLE, 'result')
        })

        test('throws error if trial already used', async () => {
            await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                isTrial: true,
            })

            await expectToThrowGQLError(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: { id: organization.id },
                    subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                    isTrial: true,
                })
            }, ERRORS.TRIAL_ALREADY_USED, 'result')
        })
    })

    describe('Paid Subscription', () => {
        test('creates subscription context with status CREATED, multiPayment, and directPaymentUrl', async () => {
            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                isTrial: false,
            })

            expect(result.subscriptionContexts[0]).toBeDefined()
            expect(result.subscriptionContexts[0].status).toBe(SUBSCRIPTION_CONTEXT_STATUS.CREATED)
            expect(result.subscriptionContexts[0].isTrial).toBe(false)
            expect(result.subscriptionContexts[0].invoice).toBeDefined()
            expect(result.subscriptionContexts[0].organization.id).toBe(organization.id)
            expect(result.subscriptionContexts[0].subscriptionPlan.id).toBe(subscriptionPlan.id)
            expect(result.subscriptionContexts[0].subscriptionPlanPricingRule.id).toBe(pricingRule.id)
            expect(result.multiPayment).toBeDefined()
            expect(result.directPaymentUrl).toBeDefined()
            expect(typeof result.directPaymentUrl).toBe('string')
        })

        test('calculates correct subscription dates based on pricing rule period', async () => {
            const [yearlyRule] = await createTestSubscriptionPlanPricingRule(admin, subscriptionPlan, {
                period: SUBSCRIPTION_PERIOD.YEAR,
                price: '10000.00',
                currencyCode: 'RUB',
            })

            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: yearlyRule.id }],
                isTrial: false,
            })

            const context = result.subscriptionContexts[0]
            const startAt = dayjs(context.startAt)
            const endAt = dayjs(context.endAt)
            expect(endAt.diff(startAt, 'month')).toBe(12)
        })

        test('extends subscription from last active context end date', async () => {
            const existingEndAt = dayjs().add(30, 'days')
            await createTestSubscriptionContext(admin, organization, subscriptionPlan, {
                startAt: dayjs().format('YYYY-MM-DD'),
                endAt: existingEndAt.format('YYYY-MM-DD'),
                isTrial: false,
                status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
            })

            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                isTrial: false,
            })

            const context = result.subscriptionContexts[0]
            const startAt = dayjs(context.startAt)
            expect(startAt.format('YYYY-MM-DD')).toBe(existingEndAt.format('YYYY-MM-DD'))
        })

        test('only considers DONE status contexts when calculating start date', async () => {
            const existingDoneEndDate = dayjs().add(10, 'day')
            await createTestSubscriptionContext(admin, organization, subscriptionPlan, {
                startAt: dayjs().format('YYYY-MM-DD'),
                endAt: existingDoneEndDate.format('YYYY-MM-DD'),
                status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
                isTrial: false,
            })

            await createTestSubscriptionContext(admin, organization, subscriptionPlan, {
                startAt: existingDoneEndDate.format('YYYY-MM-DD'),
                endAt: dayjs().add(40, 'day').format('YYYY-MM-DD'),
                status: SUBSCRIPTION_CONTEXT_STATUS.CREATED,
                isTrial: false,
            })

            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                isTrial: false,
            })

            const context = result.subscriptionContexts[0]
            const startAt = dayjs(context.startAt)
            expect(startAt.format('YYYY-MM-DD')).toBe(existingDoneEndDate.format('YYYY-MM-DD'))
        })
    })

    describe('Validation', () => {
        test('throws error if organization not found', async () => {
            const fakeOrg = { id: '00000000-0000-0000-0000-000000000000' }

            await expectToThrowAccessDeniedErrorToResult(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: fakeOrg,
                    subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                    isTrial: true,
                })
            })
        })

        test('throws error if pricing rule not found', async () => {
            const fakeRule = { id: '00000000-0000-0000-0000-000000000000' }

            await expectToThrowGQLError(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: { id: organization.id },
                    subscriptionPlanPricingRules: [fakeRule],
                    isTrial: true,
                })
            }, ERRORS.PRICING_RULE_NOT_FOUND, 'result')
        })

        test('allows registration for hidden plan (isHidden only hides from frontend)', async () => {
            const [hiddenPlan] = await createTestSubscriptionPlan(admin, {
                name: faker.commerce.productName(),
                organizationType: MANAGING_COMPANY_TYPE,
                isHidden: true,
                trialDays: 14,
            })
            const [hiddenPlanRule] = await createTestSubscriptionPlanPricingRule(admin, hiddenPlan, {
                period: SUBSCRIPTION_PERIOD.MONTH,
                price: '1000.00',
                currencyCode: 'RUB',
            })

            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: hiddenPlanRule.id }],
                isTrial: true,
            })
            expect(result.subscriptionContexts[0]).toBeDefined()
            expect(result.subscriptionContexts[0].id).toBeDefined()
        })

        test('throws error if organization type does not match plan', async () => {
            const [servicePlan] = await createTestSubscriptionPlan(admin, {
                name: faker.commerce.productName(),
                organizationType: 'SERVICE_PROVIDER',
                isHidden: false,
                trialDays: 14,
            })
            const [servicePlanRule] = await createTestSubscriptionPlanPricingRule(admin, servicePlan, {
                period: SUBSCRIPTION_PERIOD.MONTH,
                price: '1000.00',
                currencyCode: 'RUB',
            })

            await expectToThrowGQLError(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: { id: organization.id },
                    subscriptionPlanPricingRules: [{ id: servicePlanRule.id }],
                    isTrial: true,
                })
            }, ERRORS.INVALID_ORGANIZATION_TYPE, 'result')
        })
    })

    describe('Context Reuse Logic', () => {
        test('reuses existing CREATED context for same startAt (today)', async () => {
            const [firstRegisteredContext] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                isTrial: false,
            })

            const [sameRegisteredContext] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                isTrial: false,
            })

            expect(sameRegisteredContext.subscriptionContexts[0].id).toBe(firstRegisteredContext.subscriptionContexts[0].id)
        })

        test('reuses existing PENDING context from buffer period', async () => {
            const [firstRegisteredContext] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                isTrial: false,
            })

            await updateTestSubscriptionContext(admin, firstRegisteredContext.subscriptionContexts[0].id, {
                status: SUBSCRIPTION_CONTEXT_STATUS.PENDING,
            })

            const [sameRegisteredContext] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                isTrial: false,
            })

            expect(sameRegisteredContext.subscriptionContexts[0].id).toBe(firstRegisteredContext.subscriptionContexts[0].id)
            expect(sameRegisteredContext.subscriptionContexts[0].status).toBe(SUBSCRIPTION_CONTEXT_STATUS.PENDING)
        })

        test('does not reuse PENDING context older than buffer period', async () => {
            const bufferDays = 5
            const oldDate = dayjs().subtract(bufferDays + 1, 'days').startOf('day').format('YYYY-MM-DD')
            const [existingContext] = await createTestSubscriptionContext(admin, organization, subscriptionPlan, {
                subscriptionPlanPricingRule: { connect: { id: pricingRule.id } },
                startAt: oldDate,
                endAt: dayjs(oldDate).add(1, 'month').format('YYYY-MM-DD'),
                status: SUBSCRIPTION_CONTEXT_STATUS.PENDING,
                isTrial: false,
            })

            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                isTrial: false,
            })

            expect(result.subscriptionContexts[0].id).not.toBe(existingContext.id)
            expect(result.subscriptionContexts[0].status).toBe(SUBSCRIPTION_CONTEXT_STATUS.CREATED)
        })

        test('does not reuse ERROR context (final error status)', async () => {
            const yesterday = dayjs().subtract(1, 'day').startOf('day').format('YYYY-MM-DD')
            const [existingContext] = await createTestSubscriptionContext(admin, organization, subscriptionPlan, {
                subscriptionPlanPricingRule: { connect: { id: pricingRule.id } },
                startAt: yesterday,
                endAt: dayjs(yesterday).add(1, 'month').format('YYYY-MM-DD'),
                status: SUBSCRIPTION_CONTEXT_STATUS.ERROR,
                isTrial: false,
            })

            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                isTrial: false,
            })

            expect(result.subscriptionContexts[0].id).not.toBe(existingContext.id)
            expect(result.subscriptionContexts[0].status).toBe(SUBSCRIPTION_CONTEXT_STATUS.CREATED)
        })

        test('creates new context when no reusable context exists', async () => {
            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: pricingRule.id }],
                isTrial: false,
            })

            expect(result.subscriptionContexts[0]).toBeDefined()
            expect(result.subscriptionContexts[0].status).toBe(SUBSCRIPTION_CONTEXT_STATUS.CREATED)
        })
    })

    describe('Superset Plan Guard', () => {
        let supersetPlan, supersetPricingRule
        let subsetPlan, subsetPricingRule
        let nonSubsetPlan, nonSubsetPricingRule

        beforeAll(async () => {
            const [sPlan] = await createTestSubscriptionPlan(admin, {
                name: faker.commerce.productName(),
                organizationType: MANAGING_COMPANY_TYPE,
                isHidden: false,
                news: true,
                tickets: true,
            })
            supersetPlan = sPlan
            const [sRule] = await createTestSubscriptionPlanPricingRule(admin, supersetPlan, {
                period: SUBSCRIPTION_PERIOD.MONTH,
                price: '2000.00',
                currencyCode: 'RUB',
            })
            supersetPricingRule = sRule

            const [subPlan] = await createTestSubscriptionPlan(admin, {
                name: faker.commerce.productName(),
                organizationType: MANAGING_COMPANY_TYPE,
                isHidden: false,
                news: true,
            })
            subsetPlan = subPlan
            const [subRule] = await createTestSubscriptionPlanPricingRule(admin, subsetPlan, {
                period: SUBSCRIPTION_PERIOD.MONTH,
                price: '1000.00',
                currencyCode: 'RUB',
            })
            subsetPricingRule = subRule

            const [nsPlan] = await createTestSubscriptionPlan(admin, {
                name: faker.commerce.productName(),
                organizationType: MANAGING_COMPANY_TYPE,
                isHidden: false,
                ai: true,
            })
            nonSubsetPlan = nsPlan
            const [nsRule] = await createTestSubscriptionPlanPricingRule(admin, nonSubsetPlan, {
                period: SUBSCRIPTION_PERIOD.MONTH,
                price: '1500.00',
                currencyCode: 'RUB',
            })
            nonSubsetPricingRule = nsRule
        })

        test('throws ACTIVE_SUPERSET_PLAN_EXISTS when registering a paid subset plan while a non-trial superset is active', async () => {
            await createTestSubscriptionContext(admin, organization, supersetPlan, {
                startAt: dayjs().format('YYYY-MM-DD'),
                endAt: dayjs().add(1, 'month').format('YYYY-MM-DD'),
                isTrial: false,
                status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
            })

            await expectToThrowGQLError(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: { id: organization.id },
                    subscriptionPlanPricingRules: [{ id: subsetPricingRule.id }],
                    isTrial: false,
                })
            }, ERRORS.ACTIVE_SUPERSET_PLAN_EXISTS, 'result')
        })

        test('allows paid registration of subset plan when active superset is trial', async () => {
            await createTestSubscriptionContext(admin, organization, supersetPlan, {
                startAt: dayjs().format('YYYY-MM-DD'),
                endAt: dayjs().add(1, 'month').format('YYYY-MM-DD'),
                isTrial: true,
                status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
            })

            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: subsetPricingRule.id }],
                isTrial: false,
            })

            expect(result.subscriptionContexts[0].status).toBe(SUBSCRIPTION_CONTEXT_STATUS.CREATED)
        })

        test('allows paid registration of non-subset plan when non-trial superset is active', async () => {
            await createTestSubscriptionContext(admin, organization, supersetPlan, {
                startAt: dayjs().format('YYYY-MM-DD'),
                endAt: dayjs().add(1, 'month').format('YYYY-MM-DD'),
                isTrial: false,
                status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
            })

            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: nonSubsetPricingRule.id }],
                isTrial: false,
            })

            expect(result.subscriptionContexts[0].status).toBe(SUBSCRIPTION_CONTEXT_STATUS.CREATED)
        })

        test('allows paid renewal of the same plan (same plan is excluded from superset check)', async () => {
            await createTestSubscriptionContext(admin, organization, supersetPlan, {
                startAt: dayjs().format('YYYY-MM-DD'),
                endAt: dayjs().add(1, 'month').format('YYYY-MM-DD'),
                isTrial: false,
                status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
            })

            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: supersetPricingRule.id }],
                isTrial: false,
            })

            expect(result.subscriptionContexts[0].status).toBe(SUBSCRIPTION_CONTEXT_STATUS.CREATED)
            expect(result.subscriptionContexts[0].subscriptionPlan.id).toBe(supersetPlan.id)
        })

        test('allows paid registration of subset plan when superset context has expired', async () => {
            await createTestSubscriptionContext(admin, organization, supersetPlan, {
                startAt: dayjs().subtract(2, 'months').format('YYYY-MM-DD'),
                endAt: dayjs().subtract(10, 'day').format('YYYY-MM-DD'),
                isTrial: false,
                status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
            })

            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: subsetPricingRule.id }],
                isTrial: false,
            })

            expect(result.subscriptionContexts[0].status).toBe(SUBSCRIPTION_CONTEXT_STATUS.CREATED)
        })

        test('trial registration of subset plan is not blocked by active non-trial superset', async () => {
            const [trialSubsetPlan] = await createTestSubscriptionPlan(admin, {
                name: faker.commerce.productName(),
                organizationType: MANAGING_COMPANY_TYPE,
                isHidden: false,
                trialDays: 14,
                news: true,
            })
            const [trialSubsetRule] = await createTestSubscriptionPlanPricingRule(admin, trialSubsetPlan, {
                period: SUBSCRIPTION_PERIOD.MONTH,
                price: '1000.00',
                currencyCode: 'RUB',
            })

            await createTestSubscriptionContext(admin, organization, supersetPlan, {
                startAt: dayjs().format('YYYY-MM-DD'),
                endAt: dayjs().add(1, 'month').format('YYYY-MM-DD'),
                isTrial: false,
                status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
            })

            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: trialSubsetRule.id }],
                isTrial: true,
            })

            expect(result.subscriptionContexts[0].isTrial).toBe(true)
            expect(result.subscriptionContexts[0].status).toBe(SUBSCRIPTION_CONTEXT_STATUS.DONE)
        })

        test('throws ACTIVE_SUPERSET_PLAN_EXISTS when registering subset plan far in future (within buffer window)', async () => {
            const bufferDays = 5

            await createTestSubscriptionContext(admin, organization, supersetPlan, {
                startAt: dayjs().add(bufferDays + 10, 'days').format('YYYY-MM-DD'),
                endAt: dayjs().add(bufferDays + 40, 'days').format('YYYY-MM-DD'),
                isTrial: false,
                status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
            })

            await expectToThrowGQLError(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: { id: organization.id },
                    subscriptionPlanPricingRules: [{ id: subsetPricingRule.id }],
                    isTrial: false,
                })
            }, ERRORS.ACTIVE_SUPERSET_PLAN_EXISTS, 'result')
        })
    })

    describe('Feature Plan Validation', () => {
        let featurePlan, featurePricingRule
        let servicePlan

        beforeAll(async () => {
            setFeatureFlag(SUBSCRIPTIONS, true)

            const [fPlan] = await createTestSubscriptionPlan(admin, {
                name: faker.commerce.productName(),
                organizationType: MANAGING_COMPANY_TYPE,
                isHidden: false,
                planType: SUBSCRIPTION_PLAN_TYPE_FEATURE,
                trialDays: 14,
                news: true,
            })
            featurePlan = fPlan

            const [fRule] = await createTestSubscriptionPlanPricingRule(admin, featurePlan, {
                period: SUBSCRIPTION_PERIOD.MONTH,
                price: '500.00',
                currencyCode: 'RUB',
            })
            featurePricingRule = fRule

            const [sPlan] = await createTestSubscriptionPlan(admin, {
                name: faker.commerce.productName(),
                organizationType: MANAGING_COMPANY_TYPE,
                isHidden: false,
                planType: SUBSCRIPTION_PLAN_TYPE_SERVICE,
                trialDays: 14,
                payments: true,
            })
            servicePlan = sPlan
        })

        afterAll(() => {
            setFeatureFlag(SUBSCRIPTIONS, false)
        })

        test('throws NO_ACTIVE_SERVICE_SUBSCRIPTION when registering feature plan without any service subscription', async () => {
            await expectToThrowGQLError(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: { id: organization.id },
                    subscriptionPlanPricingRules: [{ id: featurePricingRule.id }],
                    isTrial: false,
                })
            }, ERRORS.NO_ACTIVE_SERVICE_SUBSCRIPTION, 'result')
        })

        test('throws NO_ACTIVE_SERVICE_SUBSCRIPTION when service subscription is expired', async () => {
            const [org] = await registerNewOrganization(user, { type: MANAGING_COMPANY_TYPE })
            await createTestSubscriptionContext(admin, org, servicePlan, {
                startAt: dayjs().subtract(30, 'days').format('YYYY-MM-DD'),
                endAt: dayjs().subtract(1, 'day').format('YYYY-MM-DD'),
                isTrial: true,
                status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
            })

            await expectToThrowGQLError(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: { id: org.id },
                    subscriptionPlanPricingRules: [{ id: featurePricingRule.id }],
                    isTrial: false,
                })
            }, ERRORS.NO_ACTIVE_SERVICE_SUBSCRIPTION, 'result')
        })

        test('allows feature plan registration when active service subscription exists', async () => {
            const [org] = await registerNewOrganization(user, { type: MANAGING_COMPANY_TYPE })
            await createTestSubscriptionContext(admin, org, servicePlan, {
                startAt: dayjs().format('YYYY-MM-DD'),
                endAt: dayjs().add(30, 'days').format('YYYY-MM-DD'),
                isTrial: false,
                status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
            })

            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: org.id },
                subscriptionPlanPricingRules: [{ id: featurePricingRule.id }],
                isTrial: false,
            })

            expect(result.subscriptionContexts[0]).toBeDefined()
            expect(result.subscriptionContexts[0].subscriptionPlan.id).toBe(featurePlan.id)
            expect(result.subscriptionContexts[0].status).toBe(SUBSCRIPTION_CONTEXT_STATUS.CREATED)
        })
    })

    describe('Bundle', () => {
        let serviceBundlePlan, serviceBundleRule
        let featureAiPlan, featureAiRule
        let featureSupportPlan, featureSupportRule

        beforeAll(async () => {
            setFeatureFlag(SUBSCRIPTIONS, true)

            const [svc] = await createTestSubscriptionPlan(admin, {
                name: faker.commerce.productName(),
                organizationType: MANAGING_COMPANY_TYPE,
                isHidden: false,
                planType: SUBSCRIPTION_PLAN_TYPE_SERVICE,
                payments: true,
                meters: true,
            })
            serviceBundlePlan = svc
            const [svcRule] = await createTestSubscriptionPlanPricingRule(admin, serviceBundlePlan, {
                period: SUBSCRIPTION_PERIOD.MONTH,
                price: '2000.00',
                currencyCode: 'RUB',
            })
            serviceBundleRule = svcRule

            const [ai] = await createTestSubscriptionPlan(admin, {
                name: faker.commerce.productName(),
                organizationType: MANAGING_COMPANY_TYPE,
                isHidden: false,
                planType: SUBSCRIPTION_PLAN_TYPE_FEATURE,
                ai: true,
            })
            featureAiPlan = ai
            const [aiRule] = await createTestSubscriptionPlanPricingRule(admin, featureAiPlan, {
                period: SUBSCRIPTION_PERIOD.MONTH,
                price: '500.00',
                currencyCode: 'RUB',
            })
            featureAiRule = aiRule

            const [sup] = await createTestSubscriptionPlan(admin, {
                name: faker.commerce.productName(),
                organizationType: MANAGING_COMPANY_TYPE,
                isHidden: false,
                planType: SUBSCRIPTION_PLAN_TYPE_FEATURE,
                support: true,
            })
            featureSupportPlan = sup
            const [supRule] = await createTestSubscriptionPlanPricingRule(admin, featureSupportPlan, {
                period: SUBSCRIPTION_PERIOD.MONTH,
                price: '300.00',
                currencyCode: 'RUB',
            })
            featureSupportRule = supRule
        })

        afterAll(() => {
            setFeatureFlag(SUBSCRIPTIONS, false)
        })

        test('creates one invoice with a row per rule and one context per rule with aligned dates', async () => {
            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: serviceBundleRule.id }, { id: featureAiRule.id }, { id: featureSupportRule.id }],
                isTrial: false,
            })

            expect(result.subscriptionContexts).toHaveLength(3)

            const invoiceIds = new Set(result.subscriptionContexts.map(ctx => ctx.invoice.id))
            expect(invoiceIds.size).toBe(1)

            const startDates = new Set(result.subscriptionContexts.map(ctx => ctx.startAt))
            const endDates = new Set(result.subscriptionContexts.map(ctx => ctx.endAt))
            expect(startDates.size).toBe(1)
            expect(endDates.size).toBe(1)

            for (const ctx of result.subscriptionContexts) {
                expect(ctx.status).toBe(SUBSCRIPTION_CONTEXT_STATUS.CREATED)
            }

            const planIds = result.subscriptionContexts.map(ctx => ctx.subscriptionPlan.id).sort()
            expect(planIds).toEqual([serviceBundlePlan.id, featureAiPlan.id, featureSupportPlan.id].sort())

            expect(result.subscriptionContexts[0].invoice.rows).toHaveLength(3)
            expect(Number(result.subscriptionContexts[0].invoice.toPay)).toBe(2800)
        })

        test('paymentType=card creates a multiPayment and directPaymentUrl', async () => {
            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: serviceBundleRule.id }, { id: featureAiRule.id }],
                paymentType: 'card',
                isTrial: false,
            })

            expect(result.multiPayment).toBeDefined()
            expect(result.multiPayment).not.toBeNull()
            expect(typeof result.directPaymentUrl).toBe('string')
        })

        test('paymentType=invoice does not create a multiPayment or directPaymentUrl', async () => {
            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: serviceBundleRule.id }, { id: featureAiRule.id }],
                paymentType: 'invoice',
                isTrial: false,
            })

            expect(result.multiPayment).toBeNull()
            expect(result.directPaymentUrl).toBeNull()
            expect(result.subscriptionContexts).toHaveLength(2)
            for (const ctx of result.subscriptionContexts) {
                expect(ctx.status).toBe(SUBSCRIPTION_CONTEXT_STATUS.CREATED)
            }
        })

        test('throws MIXED_PRICING_RULE_PERIODS when rules have different periods', async () => {
            const [yearlyAiRule] = await createTestSubscriptionPlanPricingRule(admin, featureAiPlan, {
                period: SUBSCRIPTION_PERIOD.YEAR,
                price: '5000.00',
                currencyCode: 'RUB',
            })

            await expectToThrowGQLError(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: { id: organization.id },
                    subscriptionPlanPricingRules: [{ id: serviceBundleRule.id }, { id: yearlyAiRule.id }],
                    isTrial: false,
                })
            }, ERRORS.MIXED_PRICING_RULE_PERIODS, 'result')
        })

        test('throws DUPLICATE_PLAN_IN_BUNDLE when the same plan appears twice', async () => {
            await expectToThrowGQLError(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: { id: organization.id },
                    subscriptionPlanPricingRules: [{ id: serviceBundleRule.id }, { id: featureAiRule.id }, { id: featureAiRule.id }],
                    isTrial: false,
                })
            }, ERRORS.DUPLICATE_PLAN_IN_BUNDLE, 'result')
        })

        test('throws MULTIPLE_SERVICE_PLANS_IN_BUNDLE when the bundle has two service plans', async () => {
            const [otherServicePlan] = await createTestSubscriptionPlan(admin, {
                name: faker.commerce.productName(),
                organizationType: MANAGING_COMPANY_TYPE,
                isHidden: false,
                planType: SUBSCRIPTION_PLAN_TYPE_SERVICE,
                tickets: true,
            })
            const [otherServiceRule] = await createTestSubscriptionPlanPricingRule(admin, otherServicePlan, {
                period: SUBSCRIPTION_PERIOD.MONTH,
                price: '1200.00',
                currencyCode: 'RUB',
            })

            await expectToThrowGQLError(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: { id: organization.id },
                    subscriptionPlanPricingRules: [{ id: serviceBundleRule.id }, { id: otherServiceRule.id }],
                    isTrial: false,
                })
            }, ERRORS.MULTIPLE_SERVICE_PLANS_IN_BUNDLE, 'result')
        })

        test('throws FEATURE_ALREADY_IN_PLAN when a bundled feature is covered by the service plan', async () => {
            const [serviceWithAiPlan] = await createTestSubscriptionPlan(admin, {
                name: faker.commerce.productName(),
                organizationType: MANAGING_COMPANY_TYPE,
                isHidden: false,
                planType: SUBSCRIPTION_PLAN_TYPE_SERVICE,
                payments: true,
                ai: true,
            })
            const [serviceWithAiRule] = await createTestSubscriptionPlanPricingRule(admin, serviceWithAiPlan, {
                period: SUBSCRIPTION_PERIOD.MONTH,
                price: '2500.00',
                currencyCode: 'RUB',
            })

            await expectToThrowGQLError(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: { id: organization.id },
                    subscriptionPlanPricingRules: [{ id: serviceWithAiRule.id }, { id: featureAiRule.id }],
                    isTrial: false,
                })
            }, ERRORS.FEATURE_ALREADY_IN_PLAN, 'result')
        })

        test('throws TRIAL_BUNDLE_NOT_SUPPORTED when isTrial is used with additionalPricingRules', async () => {
            await expectToThrowGQLError(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: { id: organization.id },
                    subscriptionPlanPricingRules: [{ id: serviceBundleRule.id }, { id: featureAiRule.id }],
                    isTrial: true,
                })
            }, ERRORS.TRIAL_BUNDLE_NOT_SUPPORTED, 'result')
        })

        test('throws NO_ACTIVE_SERVICE_SUBSCRIPTION for a feature-only bundle without an active service subscription', async () => {
            await expectToThrowGQLError(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: { id: organization.id },
                    subscriptionPlanPricingRules: [{ id: featureAiRule.id }, { id: featureSupportRule.id }],
                    isTrial: false,
                })
            }, ERRORS.NO_ACTIVE_SERVICE_SUBSCRIPTION, 'result')
        })

        test('allows a feature-only bundle when a service subscription is active', async () => {
            const [org] = await registerNewOrganization(user, { type: MANAGING_COMPANY_TYPE })
            await createTestSubscriptionContext(admin, org, serviceBundlePlan, {
                startAt: dayjs().format('YYYY-MM-DD'),
                endAt: dayjs().add(30, 'days').format('YYYY-MM-DD'),
                isTrial: false,
                status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
            })

            const [result] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: org.id },
                subscriptionPlanPricingRules: [{ id: featureAiRule.id }, { id: featureSupportRule.id }],
                isTrial: false,
            })

            expect(result.subscriptionContexts).toHaveLength(2)
        })

        test('throws ACTIVE_SUPERSET_PLAN_EXISTS when an active plan covers the whole bundle', async () => {
            const [supersetPlan] = await createTestSubscriptionPlan(admin, {
                name: faker.commerce.productName(),
                organizationType: MANAGING_COMPANY_TYPE,
                isHidden: false,
                planType: SUBSCRIPTION_PLAN_TYPE_SERVICE,
                payments: true,
                meters: true,
                ai: true,
                support: true,
            })

            const [org] = await registerNewOrganization(user, { type: MANAGING_COMPANY_TYPE })
            await createTestSubscriptionContext(admin, org, supersetPlan, {
                startAt: dayjs().format('YYYY-MM-DD'),
                endAt: dayjs().add(1, 'month').format('YYYY-MM-DD'),
                isTrial: false,
                status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
            })

            await expectToThrowGQLError(async () => {
                await registerSubscriptionContextsByTestClient(user, {
                    organization: { id: org.id },
                    subscriptionPlanPricingRules: [{ id: serviceBundleRule.id }, { id: featureAiRule.id }, { id: featureSupportRule.id }],
                    isTrial: false,
                })
            }, ERRORS.ACTIVE_SUPERSET_PLAN_EXISTS, 'result')
        })

        test('reuses the existing CREATED bundle when the same composition is registered again', async () => {
            const [org] = await registerNewOrganization(user, { type: MANAGING_COMPANY_TYPE })

            const [first] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: org.id },
                subscriptionPlanPricingRules: [{ id: serviceBundleRule.id }, { id: featureAiRule.id }],
                isTrial: false,
            })

            const [second] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: org.id },
                subscriptionPlanPricingRules: [{ id: serviceBundleRule.id }, { id: featureAiRule.id }],
                isTrial: false,
            })

            const firstIds = new Set(first.subscriptionContexts.map(ctx => ctx.id))
            const secondIds = new Set(second.subscriptionContexts.map(ctx => ctx.id))
            expect(secondIds).toEqual(firstIds)
        })

        test('supersedes the existing CREATED bundle when the composition changes', async () => {
            const [org] = await registerNewOrganization(user, { type: MANAGING_COMPANY_TYPE })

            const [first] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: org.id },
                subscriptionPlanPricingRules: [{ id: serviceBundleRule.id }, { id: featureAiRule.id }],
                isTrial: false,
            })
            const firstInvoiceId = first.subscriptionContexts[0].invoice.id
            const firstContextIds = first.subscriptionContexts.map(ctx => ctx.id)

            const [second] = await registerSubscriptionContextsByTestClient(user, {
                organization: { id: org.id },
                subscriptionPlanPricingRules: [{ id: serviceBundleRule.id }, { id: featureSupportRule.id }],
                isTrial: false,
            })

            for (const oldContextId of firstContextIds) {
                const stillAlive = await SubscriptionContext.getAll(admin, { id: oldContextId, deletedAt: null })
                expect(stillAlive).toHaveLength(0)
            }

            const secondPlanIds = second.subscriptionContexts.map(ctx => ctx.subscriptionPlan.id).sort()
            expect(secondPlanIds).toEqual([serviceBundlePlan.id, featureSupportPlan.id].sort())
            expect(second.subscriptionContexts[0].invoice.id).not.toBe(firstInvoiceId)
        })
    })
})